					local bThreatsMinimized = false;

					local aHideControls = {
						"fellowtheme_list",
						"fellowtheme_list_iadd",
						"fellowtheme_list_iedit",
					};

					local aGMOnlyControls = {
						"fellowtheme_list_iadd",
						"fellowtheme_list_iedit",
					};

					function isGMOnlyControl(sControl)
						for _, sGMControl in ipairs(aGMOnlyControls) do
							if sControl == sGMControl then
								return true;
							end
						end

						return false;
					end

					function setThreatsControlsVisible(bVisible)
						for _, sControl in ipairs(aHideControls) do
							if window[sControl] and window[sControl].setVisible then
								if isGMOnlyControl(sControl) then
									window[sControl].setVisible(bVisible and Session.IsHost);

									if window[sControl].setEnabled then
										window[sControl].setEnabled(bVisible and Session.IsHost);
									end
								else
									window[sControl].setVisible(bVisible);
								end
							end
						end
					end

					function onButtonPress()
						bThreatsMinimized = not bThreatsMinimized;

						setThreatsControlsVisible(not bThreatsMinimized);

						if bThreatsMinimized then
							window.setSize(200, 50);
						else
							window.setSize(300, 300);
						end
					end
